package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.profile.ProfileService;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.*;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.fitnutri.backend.records.workout.ExerciseEntryInputs.*;
@SpringBootTest @ActiveProfiles("integration-test")
class ExerciseEntryV2IT {
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired ExerciseEntryV2Service service;@Autowired WorkoutEstimateService previews;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired JdbcTemplate jdbc;
 User owner;WorkoutV2TestFixtures.Catalogue catalogue;final LocalDate date=LocalDate.of(2020,1,2);
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);catalogue=WorkoutV2TestFixtures.catalogue(jdbc);}
 PreviewPeriod period(long option,String kind,String min,List<Movement> moves){return new PreviewPeriod(UUID.randomUUID(),kind,Long.toString(option),new BigDecimal(min),Map.of(),moves);}
 CreateRequest request(boolean quick,boolean unavailable){var moves=catalogue.movements().stream().map(id->new Movement(id.toString(),3L,8L,new BigDecimal("40"))).toList();var strength=period(catalogue.strengthOption(),"STRENGTH","50",moves);var cardio=period(unavailable?catalogue.unavailableOption():catalogue.cardioOption(),"ACTIVITY","20",List.of());PreviewEntry input=quick?new QuickPreview(cardio.clientEntryId(),cardio):new WorkoutPreview(UUID.randomUUID(),"Synthetic workout",List.of(strength,cardio),null);var preview=previews.previewNew(owner.getId(),new PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,input));var confirmed=withoutFingerprints(input);var ps=confirmed instanceof Quick q?List.of(q.period()):((Workout)confirmed).periods();var reviewed=new ArrayList<Period>();for(int i=0;i<ps.size();i++){var p=ps.get(i);reviewed.add(new Period(p.clientEntryId(),p.periodKind(),p.optionId(),p.durationMinutes(),p.equipmentDetails(),p.movements(),preview.periods().get(i).calculationFingerprint()));}Entry entry=quick?new Quick(input.clientEntryId(),reviewed.getFirst()):new Workout(input.clientEntryId(),"Synthetic workout",reviewed,null);return new CreateRequest(UUID.randomUUID(),date,"Australia/Sydney",RecordSource.MANUAL,preview.fingerprint(),entry);}
 long count(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE user_id=?",Long.class,owner.getId());}
 @Test void workoutSavesExactlyOneRootTwoPeriodsThreeDetailsAndMinimalProof(){var input=request(false,false);var result=service.createEntryV2(owner.getId(),input);assertFalse(result.replayed());assertEquals(1,result.roots().size());assertEquals(2,result.leaves().size());assertEquals("WORKOUT",result.roots().getFirst().kind());assertEquals(1,count("workout_record"));assertEquals(2,count("exercise_record"));assertEquals(new BigDecimal("1342.366"),jdbc.queryForObject("SELECT sum(estimated_kj) FROM exercise_record WHERE user_id=?",BigDecimal.class,owner.getId()));assertEquals(new BigDecimal("70.00"),jdbc.queryForObject("SELECT sum(duration_minutes) FROM exercise_record WHERE user_id=?",BigDecimal.class,owner.getId()));assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=?",Long.class,owner.getId()));assertTrue(service.createEntryV2(owner.getId(),input).replayed());}
 @Test void quickUnmappedPersistsNullAuthorityAndSameRootLeafIdentity(){var input=request(true,true);var result=service.createEntryV2(owner.getId(),input);assertEquals("QUICK",result.roots().getFirst().kind());assertEquals(result.roots().getFirst().id(),result.leaves().getFirst().id());assertEquals(0,count("workout_record"));var row=jdbc.queryForMap("SELECT estimated_kj,met_used,weight_kg_used,formula_version,exercise_type_id,estimate_status FROM exercise_record WHERE user_id=?",owner.getId());for(var key:List.of("estimated_kj","met_used","weight_kg_used","formula_version","exercise_type_id"))assertNull(row.get(key));assertEquals("NO_APPLICABLE_REFERENCE",row.get("estimate_status"));}
 @Test void changedWeightOrPeriodFingerprintRejectsWithoutResidue(){var input=request(false,false);jdbc.update("UPDATE weight_entry SET weight_kg=80 WHERE user_id=?",owner.getId());assertThrows(ExerciseCalculationChangedV2Exception.class,()->service.createEntryV2(owner.getId(),input));assertEquals(0,count("exercise_record"));assertEquals(0,count("workout_record"));assertEquals(0,count("submission_receipt"));var fresh=request(false,false);var w=(Workout)fresh.entry();var p=w.periods().getFirst();var bad=new Period(p.clientEntryId(),p.periodKind(),p.optionId(),p.durationMinutes(),p.equipmentDetails(),p.movements(),"0".repeat(64));var changed=new CreateRequest(fresh.submissionId(),fresh.recordDate(),fresh.zone(),fresh.source(),fresh.previewFingerprint(),new Workout(w.clientEntryId(),w.title(),List.of(bad,w.periods().get(1)),null));assertThrows(ExerciseCalculationChangedV2Exception.class,()->service.createEntryV2(owner.getId(),changed));assertEquals(0,count("submission_receipt"));}
 @Test void lateMovementInsertFailureRollsBackRootPeriodsAndReceipt(){var input=request(false,false);String function="fail_movement_"+UUID.randomUUID().toString().replace("-","");jdbc.execute("CREATE FUNCTION "+function+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.movement_catalogue_id="+catalogue.movements().get(2)+" THEN RAISE EXCEPTION 'synthetic late movement failure'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER "+function+" BEFORE INSERT ON workout_movement_log FOR EACH ROW EXECUTE FUNCTION "+function+"()");try{assertThrows(RuntimeException.class,()->service.createEntryV2(owner.getId(),input));assertEquals(0,count("workout_record"));assertEquals(0,count("exercise_record"));assertEquals(0,count("submission_receipt"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM workout_movement_log WHERE movement_catalogue_id IN (?,?,?)",Long.class,catalogue.movements().toArray()));}finally{jdbc.execute("DROP TRIGGER "+function+" ON workout_movement_log");jdbc.execute("DROP FUNCTION "+function+"()");}assertFalse(service.createEntryV2(owner.getId(),input).replayed());}
 @Test void concurrentSameSubmissionCommitsOnceThenReplaysDespiteChangedDependencies()throws Exception{var input=request(false,true);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return service.createEntryV2(owner.getId(),input);});var b=pool.submit(()->{start.await();return service.createEntryV2(owner.getId(),input);});start.countDown();var first=a.get(20,TimeUnit.SECONDS);var second=b.get(20,TimeUnit.SECONDS);assertNotEquals(first.replayed(),second.replayed());assertEquals(first.roots(),second.roots());assertEquals(first.leaves(),second.leaves());}assertEquals(1,count("workout_record"));assertEquals(2,count("exercise_record"));assertEquals(1,count("submission_receipt"));assertEquals(new BigDecimal("854.233"),jdbc.queryForObject("SELECT sum(estimated_kj) FROM exercise_record WHERE user_id=?",BigDecimal.class,owner.getId()));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM exercise_record WHERE user_id=? AND estimated_kj IS NULL",Long.class,owner.getId()));jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.strengthOption());jdbc.update("DELETE FROM weight_entry WHERE user_id=?",owner.getId());assertTrue(service.createEntryV2(owner.getId(),input).replayed());}
 @Test void inactiveOrMissingOptionCannotCreateAndDeletedIdentityStaysReserved(){var input=request(true,false);jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.cardioOption());assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->service.createEntryV2(owner.getId(),input)).code());assertEquals(0,count("submission_receipt"));jdbc.update("UPDATE exercise_option SET active=true WHERE id=?",catalogue.cardioOption());var saved=service.createEntryV2(owner.getId(),input);jdbc.update("UPDATE exercise_record SET deleted_at=now() WHERE id=?",Long.parseLong(saved.roots().getFirst().id()));var duplicate=new CreateRequest(UUID.randomUUID(),input.recordDate(),input.zone(),input.source(),input.previewFingerprint(),input.entry());assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.createEntryV2(owner.getId(),duplicate)).code());assertEquals(1,count("exercise_record"));assertEquals(1,count("submission_receipt"));assertTrue(service.createEntryV2(owner.getId(),input).replayed());}

}
